package ir.hammeydan.app

import android.app.Activity
import android.app.AlertDialog
import android.os.Bundle
import android.content.Intent
import android.graphics.*
import android.graphics.drawable.GradientDrawable
import android.net.Uri
import android.text.InputType
import android.util.Base64
import android.view.*
import android.widget.*
import org.json.*
import java.io.ByteArrayOutputStream

class MainActivity : Activity() {
    private val api=Api()
    private val prefs by lazy { getSharedPreferences("hm5",MODE_PRIVATE) }
    private var user:JSONObject?=null
    private var archive=JSONArray()
    private var dark=false
    private var page="home"
    private var generation=0
    private lateinit var body:LinearLayout
    private lateinit var banner:TextView
    private var font=Typeface.DEFAULT
    private var ink=0; private var muted=0; private var accent=0; private var paper=0; private var bg=0; private var line=0
    private var photoCallback:((String,Bitmap)->Unit)?=null
    private fun dp(n:Int)=(n*resources.displayMetrics.density+.5f).toInt()
    private fun c(hex:String)=Color.parseColor(hex)
    override fun onCreate(state:Bundle?) { super.onCreate(state); api.onSessionExpired={ clearAccount() }; dark=prefs.getBoolean("dark",false); api.token=prefs.getString("token", "").orEmpty(); user=runCatching { JSONObject(prefs.getString("user", "").orEmpty()) }.getOrNull(); font=runCatching { Typeface.createFromAsset(assets,"Vazirmatn-Regular.ttf") }.getOrDefault(Typeface.DEFAULT); archive=runCatching { JSONArray(assets.open("archive.json").bufferedReader().use { it.readText() }) }.getOrDefault(JSONArray()); show("home"); if(api.token.isNotEmpty()) api.call("state") { v,e -> if(e==null){ user=v.asObject().optJSONObject("user"); if(user==null) clearAccount() else saveAccount() } } }
    override fun onDestroy(){ api.close(); super.onDestroy() }
    private fun palette(){ ink=c(if(dark) "#EDF5F0" else "#173B30"); muted=c(if(dark) "#B4C9C0" else "#526D62"); accent=c(if(dark) "#9AE1BB" else "#17694F"); paper=c(if(dark) "#D9284338" else "#ECFFFFFF"); bg=c(if(dark) "#112820" else "#EFF7F1"); line=c(if(dark) "#456354" else "#D9E9DF"); window.statusBarColor=bg; window.navigationBarColor=bg; window.decorView.systemUiVisibility=if(dark) 0 else View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR }
    private fun shape(color:Int, radius:Int=18, border:Boolean=false)=GradientDrawable().apply { setColor(color); cornerRadius=dp(radius).toFloat(); if(border) setStroke(dp(1),line) }
    private fun col()=LinearLayout(this).apply { orientation=LinearLayout.VERTICAL; layoutDirection=View.LAYOUT_DIRECTION_RTL }
    private fun row()=LinearLayout(this).apply { orientation=LinearLayout.HORIZONTAL; layoutDirection=View.LAYOUT_DIRECTION_RTL; gravity=Gravity.CENTER_VERTICAL }
    private fun put(p:LinearLayout,v:View){ p.addView(v,LinearLayout.LayoutParams(-1,-2)) }
    private fun space(p:LinearLayout,h:Int=8){ p.addView(View(this),LinearLayout.LayoutParams(1,dp(h))) }
    private fun txt(s:String,size:Int=15,color:Int=ink,bold:Boolean=false)=TextView(this).apply { text=s; textSize=size.toFloat(); setTextColor(color); typeface=Typeface.create(font,if(bold) Typeface.BOLD else Typeface.NORMAL); gravity=Gravity.RIGHT; setLineSpacing(dp(3).toFloat(),1.08f) }
    private fun button(s:String,primary:Boolean=false,action:()->Unit)=txt(s,14,if(primary) Color.WHITE else accent,true).apply { gravity=Gravity.CENTER; setPadding(dp(10),dp(12),dp(10),dp(12)); minHeight=dp(48); background=shape(if(primary) c("#17694F") else paper,15,!primary); setOnClickListener { action() } }
    private fun pair(p:LinearLayout,a:View,b:View){ val r=row(); listOf(a,b).forEach { v->r.addView(v,LinearLayout.LayoutParams(0,-2,1f).apply { setMargins(dp(3),0,dp(3),0) }) }; put(p,r) }
    private fun card(p:LinearLayout)=col().also { it.background=shape(paper,22,true); it.setPadding(dp(15),dp(14),dp(15),dp(14)); p.addView(it,LinearLayout.LayoutParams(-1,-2).apply { setMargins(0,dp(5),0,dp(7)) }) }
    private fun title(s:String,sub:String=""){ put(body,txt(s,24,ink,true)); if(sub.isNotBlank()) put(body,txt(sub,13,muted)); space(body) }
    private fun field(h:String,multi:Boolean=false,secret:Boolean=false)=EditText(this).apply { hint=h; setTextColor(ink); setHintTextColor(muted); textSize=15f; typeface=font; gravity=Gravity.RIGHT or Gravity.TOP; inputType=InputType.TYPE_CLASS_TEXT or (if(secret) InputType.TYPE_TEXT_VARIATION_PASSWORD else if(multi) InputType.TYPE_TEXT_FLAG_MULTI_LINE else 0); setSingleLine(!multi); if(multi) minLines=3; setPadding(dp(13),dp(12),dp(13),dp(12)); background=shape(paper,13,true) }
    private fun EditText.value()=text.toString().trim()
    private fun dialog()=AlertDialog.Builder(this,if(dark) android.R.style.Theme_Material_Dialog_Alert else android.R.style.Theme_Material_Light_Dialog_Alert)
    private fun message(s:String){ if(!isFinishing) dialog().setTitle("هم‌میدان").setMessage(s).setPositiveButton("باشه",null).show() }
    private fun note(s:String){ banner.text=s; banner.visibility=if(s.isEmpty()) View.GONE else View.VISIBLE }
    private fun form()=col().apply { setPadding(dp(18),dp(8),dp(18),dp(12)) }
    private fun wrap(p:LinearLayout)=ScrollView(this).apply { addView(p) }
    private fun logged()=api.token.isNotBlank() && user!=null
    private fun need():Boolean { if(logged()) return true; account(); return false }
    private fun saveAccount(){ prefs.edit().putString("token",api.token).putString("user",user?.toString()).apply() }
    private fun clearAccount(){ user=null; api.token=""; prefs.edit().remove("token").remove("user").apply() }
    private fun mutate(action:String,p:JSONObject,success:String="",next:()->Unit={}) { api.call(action,p){ _,e-> if(e!=null) message(e) else { if(success.isNotBlank()) Toast.makeText(this,success,Toast.LENGTH_SHORT).show(); next() } } }
    private fun show(t:String){ page=t; generation++; palette(); val root=col().apply { background=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(bg,c(if(dark) "#213E33" else "#FFF5F0"),bg)); setPadding(dp(13),dp(8),dp(13),dp(8)) }; setContentView(root)
        val top=row(); val logo=ImageView(this).apply { setImageResource(R.drawable.hm_logo); scaleType=ImageView.ScaleType.CENTER_INSIDE; contentDescription="لوگوی هم‌میدان" }; top.addView(logo,LinearLayout.LayoutParams(dp(48),dp(48))); val name=col(); put(name,txt("هم‌میدان",22,ink,true)); put(name,txt("روایت · ارتباط · همدلی",11,muted)); top.addView(name,LinearLayout.LayoutParams(0,-2,1f)); top.addView(button("جست‌وجو"){show("search")}); put(root,top)
        banner=txt("",12,muted).apply { visibility=View.GONE }; put(root,banner); val scroll=ScrollView(this).apply { isFillViewport=true }; body=col().apply { setPadding(dp(2),dp(8),dp(2),dp(8)) }; scroll.addView(body); root.addView(scroll,LinearLayout.LayoutParams(-1,0,1f)); val nav=row().apply { background=shape(paper,22,true); setPadding(dp(3),dp(4),dp(3),dp(4)) }; listOf(Triple("home","⌂","خانه"),Triple("events","◇","شهر"),Triple("compose","＋","روایت"),Triple("chat","▤","پیام‌ها"),Triple("profile","○","من")).forEach { (id,icon,label)->val b=col().apply { gravity=Gravity.CENTER; if(t==id) background=shape(c(if(dark) "#355D48" else "#DDEFE3"),16); setPadding(0,dp(5),0,dp(5)); setOnClickListener { show(id) }; contentDescription=label }; put(b,txt(icon,23,accent,true).apply{gravity=Gravity.CENTER}); put(b,txt(label,11,if(t==id) accent else muted,true).apply{gravity=Gravity.CENTER}); nav.addView(b,LinearLayout.LayoutParams(0,-2,1f)) }; put(root,nav)
        when(t){ "home"->home(); "events"->events(); "compose"->compose(); "chat"->chat(); "profile"->profile(); "search"->search(); "archive"->archivePage(); "channels"->channels(); "ai"->assistant(); "mine"->mine(); "admin"->admin(); else->home() }
    }
    private fun load(endpoint:String,target:LinearLayout,cache:Boolean=false,render:(JSONArray)->Unit){ val gen=generation; if(cache) runCatching { JSONArray(prefs.getString("cache_$endpoint","").orEmpty()) }.getOrNull()?.let(render); api.call(endpoint){v,e->if(gen==generation){ if(e!=null){note(e); if(target.childCount==0) put(target,txt("اطلاعات در دسترس نیست؛ دوباره تلاش کنید.",14,muted))} else {note(""); val a=v.asArray(); if(cache) prefs.edit().putString("cache_$endpoint",a.toString()).apply(); target.removeAllViews(); render(a) } }} }
    private fun external(url:String){ try { val uri=Uri.parse(url); if(uri.scheme!="https") throw IllegalArgumentException(); startActivity(Intent(Intent.ACTION_VIEW,uri)) }catch(_:Exception){message("باز کردن این نشانی ممکن نیست.")} }
    private fun archiveCard(p:LinearLayout,a:JSONObject){val k=card(p); put(k,txt(a.optString("type")+" · "+a.optString("source"),12,accent,true)); put(k,txt(a.optString("title"),18,ink,true)); put(k,txt(a.optString("body"),14,muted)); space(k); put(k,button("اصل گزارش و تصاویر منبع"){external(a.optString("source_url"))})}
    private fun home(){ title("امروز در هم‌میدان","برای خواندن روایت‌ها نیازی به ثبت‌نام نیست."); val hero=card(body); hero.background=GradientDrawable(GradientDrawable.Orientation.TR_BL,intArrayOf(c("#14543F"),c("#258663"))).apply{cornerRadius=dp(24).toFloat()}; put(hero,txt("هر روایت، بخشی از زندگی ماست",23,Color.WHITE,true)); put(hero,txt("بخوان، تجربه‌ات را ثبت کن و با دیگران در ارتباط باش.",14,c("#E1F6E9"))); space(hero); pair(hero,button("ثبت روایت"){show("compose")},button("آرشیو مستند"){show("archive")}); pair(body,button("کانال‌ها"){show("channels")},button("همیار هوشمند"){show("ai")}); space(body); put(body,txt("استوری‌ها و روایت‌ها",19,ink,true)); put(body,button("＋ استوری تازه"){composer(true)}); val feed=col(); put(body,feed); load("feed",feed,true){a-> val items=a.objects().filter { it.optString("kind")!="story" || validStory(it) }; if(items.isEmpty()) put(card(feed),txt("هنوز روایت عمومی منتشر نشده است.",14,muted)); items.forEach {post(feed,it)} }; archive.optJSONObject(0)?.let { put(body,txt("از آرشیو مستند",18,ink,true)); archiveCard(body,it) }; put(body,button("تازه‌سازی"){show("home")}) }
    private fun validStory(p:JSONObject)=runCatching { val f=java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss",java.util.Locale.US); f.timeZone=java.util.TimeZone.getTimeZone("UTC"); val age=System.currentTimeMillis()-(f.parse(p.optString("created_at"))?.time?:0); age in 0 until 86400000L }.getOrDefault(false)
    private fun image(p:LinearLayout,x:JSONObject){ if(!x.optBoolean("has_photo"))return; val v=ImageView(this).apply { setImageResource(R.drawable.placeholder); scaleType=ImageView.ScaleType.FIT_CENTER; background=shape(line); contentDescription="تصویر روایت" }; p.addView(v,LinearLayout.LayoutParams(-1,dp(190))); api.photo(x.optInt("id")){ b->if(b!=null) BitmapFactory.decodeByteArray(b,0,b.size)?.let{v.setImageBitmap(it)} } }
    private fun post(p:LinearLayout,x:JSONObject,mine:Boolean=false){ val k=card(p); val id=x.optInt("id"); put(k,txt(x.optString("display_name","کاربر")+if(x.optString("kind")=="story") " · استوری" else "",16,accent,true)); if(mine) put(k,txt(when(x.optString("status")){"approved"->"منتشر شده";"pending"->"در انتظار بررسی";else->"رد شده"},12,muted)); put(k,txt(x.optString("body"))); image(k,x); space(k); if(mine) put(k,button("حذف روایت"){dialog().setMessage("روایت حذف شود؟").setNegativeButton("انصراف",null).setPositiveButton("حذف"){_,_->mutate("delete_post",obj("id" to id),"حذف شد"){show("mine")}}.show()}) else pair(k,button((if(x.optBoolean("liked")) "♥ " else "♡ ")+x.optInt("likes")){if(need())mutate("like",obj("id" to id)){ show(page) }},button("گزارش"){if(need())dialog().setMessage("گزارش برای مدیر ارسال شود؟").setNegativeButton("انصراف",null).setPositiveButton("گزارش"){_,_->mutate("report",obj("id" to id),"گزارش ثبت شد")}.show()}) }
    private fun archivePage(){ title("آرشیو مستند","گزارش‌های منبع‌دار؛ نه پست ساختگی کاربران."); val l=col();put(body,l); archive.objects().forEach{archiveCard(l,it)}; val gen=generation;api.call("archive"){v,e->if(gen==generation&&e==null){archive=v.asArray();l.removeAllViews();archive.objects().forEach{archiveCard(l,it)}}} }
    private fun events(){title("برنامه‌های عمومی شهر","نقشه کلی آفلاین؛ بدون موقعیت زنده افراد."); val k=card(body);val selected=txt("روی نام شهر بزنید",13,muted);val map=CityMap(this,dark){city->selected.text="شهر انتخاب‌شده: $city"}; k.addView(map,LinearLayout.LayoutParams(-1,dp(270)));put(k,selected);val l=col();put(body,l);load("events",l,true){a->if(a.length()==0)put(card(l),txt("برنامه عمومی تأییدشده‌ای ثبت نشده است.",14,muted));a.objects().forEach{x->val q=card(l);put(q,txt(x.optString("title"),18,ink,true));put(q,txt(x.optString("city")+" · "+x.optString("starts_at")+" UTC",13,muted));put(q,txt(x.optString("description")));put(q,button("منبع رسمی"){external(x.optString("source_url"))})}};put(body,button("تازه‌سازی"){show("events")})}
    private fun channels(){title("کانال‌ها","اطلاعیه‌ها و راهنما");val l=col();put(body,l);load("channels",l,true){a->a.objects().forEach{x->val k=card(l);put(k,txt(x.optString("title"),18,ink,true));put(k,txt(x.optString("body")))}};put(body,button("تازه‌سازی"){show("channels")})}
    private fun compose(){title("روایت تازه","متن یا تصویر خود را ثبت کن."); val k=card(body);put(k,button("نوشتن پست",true){composer(false)});space(k);put(k,button("استوری ۲۴ ساعته"){composer(true)});space(k);put(k,txt("تصاویر اشخاص را فقط با رضایت آن‌ها منتشر کن. روایت پس از بررسی مدیر نمایش داده می‌شود.",13,muted))}
    private fun composer(story:Boolean){if(!need())return;val f=form();val e=field("متن روایت…",true);put(f,e);space(f);var photo="";val preview=ImageView(this).apply{visibility=View.GONE;scaleType=ImageView.ScaleType.FIT_CENTER};f.addView(preview,LinearLayout.LayoutParams(-1,dp(130)));put(f,button("انتخاب تصویر"){photoCallback={raw,bmp->photo=raw;preview.setImageBitmap(bmp);preview.visibility=View.VISIBLE};try{startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply{type="image/*";addCategory(Intent.CATEGORY_OPENABLE)},42)}catch(_:Exception){message("انتخاب تصویر ممکن نیست.")}});val d=dialog().setTitle(if(story)"استوری تازه" else "پست تازه").setView(wrap(f)).setNegativeButton("انصراف",null).setPositiveButton("ارسال",null).create();d.setOnDismissListener{photoCallback=null};d.show();d.getButton(-1).setOnClickListener{if(e.value().isEmpty()&&photo.isEmpty()){e.error="متن یا تصویر لازم است";return@setOnClickListener};d.getButton(-1).isEnabled=false;api.call("publish",obj("kind" to if(story)"story" else "post","body" to e.value(),"photo" to photo)){_,err->if(err!=null){d.getButton(-1).isEnabled=true;message(err)}else{d.dismiss();message("روایت ثبت شد و در انتظار بررسی است.");show("mine")}}}}
    override fun onActivityResult(requestCode:Int,resultCode:Int,data:Intent?){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=42||resultCode!=RESULT_OK)return;val uri=data?.data?:return;val cb=photoCallback?:return;api.work{try{val o=BitmapFactory.Options().apply{inJustDecodeBounds=true};contentResolver.openInputStream(uri).use{BitmapFactory.decodeStream(it,null,o)};require(o.outWidth>0&&o.outHeight>0);o.inSampleSize=1;while(maxOf(o.outWidth,o.outHeight)/o.inSampleSize>1600)o.inSampleSize*=2;o.inJustDecodeBounds=false;val bmp=contentResolver.openInputStream(uri).use{BitmapFactory.decodeStream(it,null,o)}?:error("image");val out=ByteArrayOutputStream();bmp.compress(Bitmap.CompressFormat.JPEG,78,out);require(out.size()<3000000);val raw="data:image/jpeg;base64,"+Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP);api.main{if(photoCallback===cb)cb(raw,bmp)}}catch(_:Exception){api.main{message("تصویر قابل خواندن نیست یا حجم آن زیاد است.")}}}}
    private fun account(){val f=form();put(f,txt("برای انتشار روایت یا پیام، یک نام کاربری انتخاب کن.",14,muted));val n=field("نام کاربری فارسی یا لاتین");val dname=field("نام نمایشی (اختیاری)");val pass=field("رمز عبور حداقل ۸ کاراکتر",secret=true);val discover=CheckBox(this).apply{text="نمایش داوطلبانه در جست‌وجو";setTextColor(ink);typeface=font};put(f,n);put(f,discover);put(f,txt("حساب مهمان بعد از خروج قابل بازیابی نیست.",12,muted));val d=dialog().setTitle("ورود به هم‌میدان").setView(wrap(f)).setNegativeButton("بعداً",null).create();var busy=false;fun join(kind:String){if(busy)return;if(n.value().length<3){n.error="حداقل ۳ کاراکتر";return};if(kind!="guest"&&pass.value().length<8){pass.error="حداقل ۸ کاراکتر";return};busy=true;api.call(kind,obj("username" to n.value(),"display_name" to dname.value(),"password" to if(kind=="guest")"" else pass.value(),"discoverable" to discover.isChecked)){v,e->busy=false;if(!d.isShowing)return@call;if(e!=null){message(e)}else{val x=v.asObject();val u=x.optJSONObject("user");val token=x.optString("token");if(u==null||token.isBlank()){message("پاسخ ورود ناقص است.")}else{api.token=token;user=u;saveAccount();d.dismiss();show(page)}}}};put(f,button("ورود با مهمان",true){join("guest")});space(f);put(f,dname);space(f);put(f,pass);space(f);pair(f,button("ساخت حساب"){join("register")},button("ورود با رمز"){join("login")});d.show()}
    private fun profile(){title("حساب من","تنظیمات و روایت‌های شخصی");val k=card(body);if(logged()){val u=user!!;put(k,txt(u.optString("display_name"),20,ink,true));put(k,txt("@"+u.optString("username"),13,muted));put(k,button("روایت‌های من"){show("mine")});val vis=u.optBoolean("discoverable");put(k,button(if(vis)"مخفی کردن از جست‌وجو" else "نمایش در جست‌وجو"){mutate("discoverability",obj("enabled" to !vis),"تنظیم شد"){u.put("discoverable",!vis);saveAccount();show("profile")}});if(u.optString("role")=="admin")put(k,button("مدیریت محتوا"){show("admin")})else put(k,button("فعال‌سازی مدیر"){val e=field("کلید خصوصی مدیر",secret=true);dialog().setTitle("فعال‌سازی مدیر").setView(e).setNegativeButton("انصراف",null).setPositiveButton("فعال‌سازی"){_,_->mutate("claim_admin",obj("key" to e.value()),"مدیر فعال شد"){u.put("role","admin");saveAccount();show("profile")}}.show()});put(k,button("خروج"){dialog().setMessage(if(u.optBoolean("guest"))"حساب مهمان پس از خروج بازیابی نمی‌شود. خارج می‌شوید؟" else "از حساب خارج می‌شوید؟").setNegativeButton("انصراف",null).setPositiveButton("خروج"){_,_->mutate("logout",obj()){clearAccount();show("home")}}.show()})}else{put(k,txt("به هم‌میدان خوش آمدی",18,ink,true));put(k,button("ورود / حساب مهمان",true){account()})};val s=card(body);put(s,button(if(dark)"پوسته روشن" else "پوسته تاریک"){dark=!dark;prefs.edit().putBoolean("dark",dark).apply();show("profile")});put(s,button("بررسی اتصال سرور"){api.call("health"){v,e->message(e?:"سرور پاسخ داد. نسخه: "+v.asObject().optString("version")+"\nتصویر: "+(if(v.asObject().optBoolean("images"))"فعال" else "GD تنظیم نشده"))}});put(s,txt("نسخه ۵ · Kotlin Native",12,muted))}
    private fun mine(){title("روایت‌های من");if(!logged()){put(body,button("ورود",true){account()});return};val l=col();put(body,l);load("mine",l){a->if(a.length()==0)put(l,txt("هنوز روایتی ثبت نکرده‌ای.",14,muted));a.objects().forEach{post(l,it,true)}}}
    private fun search(){title("جست‌وجو","روایت‌ها و کاربران داوطلب نمایش در جست‌وجو");val e=field("نام کاربری یا موضوع");put(body,e);space(body);val results=col();put(body,button("جست‌وجو",true){val q=e.value();results.removeAllViews();if(q.isBlank()){e.error="عبارت جست‌وجو را بنویس";return@button};archive.objects().filter{(it.optString("title")+it.optString("body")).contains(q,true)}.forEach{archiveCard(results,it)};runCatching{JSONArray(prefs.getString("cache_feed","").orEmpty())}.getOrNull()?.objects()?.filter{it.optString("body").contains(q,true)&& (it.optString("kind")!="story"||validStory(it))}?.forEach{post(results,it)};if(!logged()){put(results,button("ورود برای جست‌وجوی کاربران"){account()});return@button};val gen=generation;api.call("search&q="+enc(q)){v,err->if(gen==generation){if(err!=null)note(err)else{val a=v.asArray();if(a.length()==0)put(results,txt("کاربری پیدا نشد.",14,muted));a.objects().forEach{x->val k=card(results);put(k,txt(x.optString("display_name")+" @"+x.optString("username"),16,ink,true));put(k,button("درخواست گفتگو"){mutate("request",obj("username" to x.optString("username")),"درخواست ارسال شد.")})}}}}});put(body,results)}
    private fun chat(){title("پیام‌ها","گفتگوی خصوصی با پذیرش مخاطب");if(!logged()){put(body,button("ورود یا حساب مهمان",true){account()});return};pair(body,button("یافتن کاربر",true){show("search")},button("تازه‌سازی"){show("chat")});val l=col();put(body,l);load("contacts",l){a->if(a.length()==0)put(l,txt("هنوز گفتگویی نداری.",14,muted));a.objects().forEach{x->val k=card(l);val peer=x.optInt("id");put(k,txt(x.optString("display_name"),17,ink,true));if(x.optBoolean("accepted"))put(k,button("باز کردن گفتگو",true){conversation(peer,x.optString("display_name"))})else if(x.optInt("recipient")==user?.optInt("id"))put(k,button("پذیرفتن درخواست",true){mutate("accept",obj("id" to peer),"پذیرفته شد"){show("chat")}})else put(k,txt("منتظر پذیرش درخواست",13,muted));put(k,button("قطع ارتباط"){dialog().setMessage("ارتباط حذف شود؟").setNegativeButton("انصراف",null).setPositiveButton("قطع ارتباط"){_,_->mutate("block",obj("id" to peer),"حذف شد"){show("chat")}}.show()})}}}
    private fun conversation(peer:Int,name:String){generation++;body.removeAllViews();title(name,"پیام خصوصی");val l=col();put(body,l);val e=field("پیام خود را بنویس…");put(body,e);fun refresh(){load("messages&id=$peer",l){a->a.objects().forEach{x->val k=card(l);put(k,txt(if(x.optInt("sender")==user?.optInt("id"))"من" else name,12,accent,true));put(k,txt(x.optString("body")))}}};put(body,button("ارسال",true){if(e.value().isBlank()){e.error="پیام را بنویس"}else mutate("send",obj("id" to peer,"body" to e.value())){e.setText("");refresh()}});pair(body,button("تازه‌سازی"){refresh()},button("بازگشت"){show("chat")});refresh()}
    private fun assistant(){title("همیار هوشمند","نگارش و خلاصه‌سازی متن عمومی");val e=field("چه کمکی می‌خواهی؟",true);put(body,e);val ans=card(body);put(ans,txt("پاسخ همیار اینجا نمایش داده می‌شود.",14,muted));put(body,button("ارسال",true){if(!need())return@button;if(e.value().isBlank()){e.error="درخواستت را بنویس";return@button};ans.removeAllViews();put(ans,txt("در حال دریافت پاسخ…"));api.call("ai",obj("body" to e.value())){v,err->ans.removeAllViews();put(ans,txt(err?:v.asObject().optString("answer")))}})}
    private fun admin(){title("مدیریت محتوا");val l=col();put(body,l);load("moderation",l){a->if(a.length()==0)put(l,txt("موردی برای بررسی نیست.",14,muted));a.objects().forEach{x->val k=card(l);put(k,txt(x.optString("body")));image(k,x);pair(k,button("تأیید",true){mutate("review",obj("id" to x.optInt("id"),"status" to "approved"),"منتشر شد"){show("admin")}},button("رد"){mutate("review",obj("id" to x.optInt("id"),"status" to "rejected"),"رد شد"){show("admin")}})}};put(body,button("اطلاعیه تازه"){val f=form();val t=field("عنوان");val b=field("متن",true);put(f,t);put(f,b);dialog().setTitle("اطلاعیه کانال").setView(f).setNegativeButton("انصراف",null).setPositiveButton("انتشار"){_,_->mutate("channel_add",obj("title" to t.value(),"body" to b.value()),"منتشر شد")}.show()})}
    override fun onBackPressed(){if(page!="home")show("home")else super.onBackPressed()}
}
